def remove(self, match_fields):
    """Remove the rule with these match fields; returns it, or None."""
    key = FlowRule(match_fields, []).key()
    rule = self._find(key)
    if rule is None:
        return None
    self.rules.remove(rule)
    return rule

def clear(self):
    """Remove every rule from the table."""
    self.rules = []
    return 0

# ------------------------------------------------------------------
# lookup and statistics
# ------------------------------------------------------------------
def lookup(self, packet_headers):
    """Highest-priority rule matching ``packet_headers``, or None."""
    best = None
    best_rank = None
    for index, rule in enumerate(self.rules):
        if not rule.matches(packet_headers):
            continue
        rank = (rule.priority, len(rule.match_fields), -index)
        if best_rank is None or rank > best_rank:
            best, best_rank = rule, rank
    return best

def evict_expired(self, current_time, last_matched_times=None):
    """Evict every expired rule; returns how many were removed.

    ``last_matched_times`` supplies the idle-timeout reference per rule.  It
    may be a mapping keyed by rule object or by the rule's match key, or a
    callable taking the rule; rules missing from it fall back to their
    installation time.
    """
    expired = [rule for rule in self.rules
               if rule.is_expired(current_time,
                                  self._last_matched(rule,
                                                     last_matched_times))]
    for rule in expired:
        self.rules.remove(rule)
    self.evicted.extend(expired)
    return len(expired)

@staticmethod
def _last_matched(rule, last_matched_times):
    if last_matched_times is None:
        return None
    if callable(last_matched_times):
        return last_matched_times(rule)
    if rule in last_matched_times:
        return last_matched_times[rule]
    return last_matched_times.get(rule.key())

def stats(self):
    """``(rule, packet_count, byte_count)`` for every installed rule."""
    return [(rule, rule.packet_count, rule.byte_count)
            for rule in self.rules]

def size(self):
    """Number of rules currently installed."""
    return len(self.rules)

def utilization(self):
    """Fraction of the table's capacity in use."""
    if self.capacity <= 0:
        return 0.0
    return len(self.rules) / float(self.capacity)
